"""Table procedures checked in the supplied French core book.

These are independently written reminders. PDF pages are recorded explicitly;
the compact procedure fields must never be inferred from a different edition.
"""

def supplement(rules, R):
    def P(page,title,summary,*,test=None,opposition=None,threshold=None,action=None,effect=None,limits=None,kit=(),tags=(),original=None,topic='combat',example=None,steps=()):
        R('core',page,title,summary,steps=steps,topic=topic,kind='action' if action else 'rule',original=original,tags=tags)
        card=rules[-1]
        card['procedure']={k:v for k,v in dict(test=test,opposition=opposition,threshold=threshold,action=action,effect=effect,limits=limits,example=example).items() if v}
        card['kit']=list(kit)
        card['practical']=True

    P(101,'Tirer avec une arme à feu','Choisir une cible à une portée autorisée par le profil de l’arme. Comparer le SO à cette portée au SD, résoudre l’attaque, puis faire résister la cible aux dommages.',test='Armes à feu + Agilité',opposition='Réaction + Intuition',action='1 action majeure · à son tour',effect='VD de l’arme + succès nets ; la cible retranche ses succès de Constitution. Une égalité inflige la VD de base dans cette édition.',kit=('pistolet','fusil','munitions','smartgun'),tags=('tirer sur une cible','faire feu','tir','shoot','gun','attaquer à distance'),original='Armes à feu',example='Armes à feu 5 + AGI 4 = 9D6. Avec 4 succès contre 2, ajouter 2 à la VD avant l’encaissement.')
    P(103,'Frapper au corps à corps','Utiliser la même compétence pour les poings, les lames et les armes contondantes. Le SO et la VD viennent de l’arme ou du profil à mains nues.',test='Combat rapproché + Agilité',opposition='Réaction + Intuition',action='1 action majeure · à son tour',effect='Ajouter les succès nets à la VD, puis résistance avec Constitution.',kit=('couteau','matraque','gants'),tags=('frapper','poing','bagarre','mêlée','attaquer au couteau'),original='Combat rapproché')
    P(101,'Utiliser une arme exotique','La compétence exige une spécialisation correspondant à l’arme. Une première spécialisation est obtenue avec la compétence ; le même rang sert aux autres spécialisations achetées.',test='Armes exotiques + Agilité',opposition='Réaction + Intuition',action='1 action majeure',limits='Pas d’utilisation inexpérimentée ; posséder la spécialisation de l’arme.',kit=('armes exotiques',),original='Armes exotiques')
    P(102,'Lancer une arme de jet','L’attaque emploie Athlétisme plutôt qu’Armes à feu. Utiliser la portée et les dommages de l’objet lancé ; une grenade suit sa procédure d’explosion et de déviation.',test='Athlétisme + Agilité',opposition='Réaction + Intuition pour une arme visant directement une cible',action='1 action majeure',kit=('couteau de lancer','shuriken','grenade'),tags=('lancer couteau','arme de jet','lancer objet','throw'))
    P(114,'Combattre à mains nues','Les poings utilisent une VD de base de 2E et un SO égal à Force + Réaction. Pour la mêlée et les armes lancées, une Force d’au moins 7 ajoute 1 à la VD ; à partir de 10, le bonus devient 2.',test='Combat rapproché + Agilité',opposition='Réaction + Intuition',action='1 action majeure',effect='Dommages étourdissants ; les augmentations ou pouvoirs peuvent modifier le profil.',tags=('mains nues','boxer','force dommages','unarmed'))
    P(48,'Bloquer une attaque de mêlée','Conserver une action mineure permet d’améliorer un seul test de défense au corps à corps.',test='Réaction + Intuition + Combat rapproché',opposition='Jet d’attaque adverse',action='1 action mineure · à tout moment',limits='Un seul test de défense ; réservé au corps à corps.',original='Bloquer (L)',tags=('parer','parade','se défendre','block'))
    P(48,'Esquiver une attaque','Ajouter Athlétisme à un seul test de défense. Il faut disposer d’une action mineure au moment de l’attaque.',test='Réaction + Intuition + Athlétisme',opposition='Jet d’attaque adverse',action='1 action mineure · à tout moment',limits='Le bonus ne dure que pour ce test.',original='Esquiver (L)',tags=('esquive','dodge','éviter balle','se défendre'))
    P(50,'Se mettre en défense totale','Ajouter sa Volonté aux tests de défense jusqu’à la fin du round en échange d’une action majeure.',test='Réaction + Intuition + Volonté',action='1 action majeure · à tout moment',effect='Bonus sur les tests de défense jusqu’à la fin du round.',original='Défense totale (L)',tags=('défense totale','full defense'))
    P(48,'Viser une zone précise : Cibler','Cibler augmente les dommages d’une attaque de 2, en échange d’un malus de 4 dés sur sa réserve. Certaines actions d’Atout permettent d’autres ciblages.',action='1 action mineure + l’action majeure Attaquer',test='Réserve d’attaque − 4 dés',effect='VD +2.',original='Cibler (I)',tags=('tir appelé','viser tête','called shot'))
    P(48,'Attaquer depuis un couvert','Pour attaquer tout en conservant l’état Couvert, dépenser cette action mineure en même temps que l’action Attaquer.',action='1 mineure + 1 majeure Attaquer',original='Attaquer depuis un couvert (I)',tags=('tirer couvert','abri'))
    P(48,'Attaquer plusieurs adversaires','Les cibles doivent être accessibles, à portée, et les munitions suffisantes. Répartir la réserve entre elles ; pour deux méthodes d’attaque différentes, utiliser la moitié de chaque réserve, arrondie à l’inférieur.',test='Réserve d’attaque partagée',action='1 mineure + 1 majeure Attaquer',original='Attaques multiples (I)',tags=('attaques multiples','deux cibles','multiattaque'))
    P(48,'Donner un ordre à un drone','Un ordre à un drone contrôlé coûte une action mineure. Avec une CCR, le même ordre peut être envoyé à tous les drones ; des ordres différents exigent des actions séparées.',action='1 action mineure · à son tour',kit=('console de commande pour rigger','drone'),topic='rigging',original='Commander un drone (I)',tags=('commander drone','ordonner drone'))
    P(48,'Dégainer rapidement une petite arme','Dégainer un pistolet, une arme de taille comparable ou une petite arme de jet et attaquer immédiatement. Le trait, l’augmentation ou le matériel autorisant ce geste est obligatoire.',action='1 mineure + 1 majeure Attaquer',kit=('holster rapide',),original='Dégainer rapidement (I)',tags=('quick draw','dégainer'))
    P(48,'Changer le mode d’un appareil connecté','Avec une interface neurale directe, changer le mode d’un appareil : tir d’un smartgun, sans-fil, activation d’un implant ou mode silencieux du commlink.',action='1 action mineure · à tout moment',kit=('smartgun','commlink','interface neurale'),original='Changer le mode d’un appareil (L)',tags=('changer mode tir','couper sans fil'))
    P(48,'Faire trébucher une cible','Combiner cette action avec une attaque de mêlée. Réduire la VD de base de 2. Si l’attaque réussit, la cible teste son équilibre au lieu de subir simplement une mise à terre automatique.',action='1 mineure + 1 majeure Attaquer',test='Attaque de mêlée normale',opposition='Puis Athlétisme + Agilité de la cible, seuil égal à la VD ajustée',effect='Si la cible échoue à ce second test, elle est À terre.',original='Faire trébucher (I)',tags=('croche-pied','mettre à terre'))
    P(48,'Éviter une explosion ou un gaz','Choisir sa direction avant de connaître la déviation. Chaque succès permet de se déplacer d’un mètre ; au-delà de 2 mètres, terminer À terre.',test='Réaction + Athlétisme − malus d’évitement',action='1 action mineure · hors de son tour',effect='Malus : −6 au point d’impact, −4 à portée Proche, −2 à portée Courte.',limits='Impossible après Éviter, Se déplacer ou Sprinter ce round ; interdit aussi ces déplacements pour le reste du round.',original='Éviter (L)',tags=('esquiver grenade','explosion','plonger au sol','gaz'))
    P(49,'Intercepter un adversaire en mêlée','Lorsqu’un adversaire arrive à portée proche, attaquer immédiatement au corps à corps en interrompant l’ordre d’initiative.',action='1 mineure + 1 majeure encore disponibles',limits='Les deux actions doivent rester en réserve ; aucune arme à distance.',original='Intercepter (L)',tags=('attaque opportunité','interception'))
    P(49,'Se déplacer pendant un combat','Parcourir jusqu’à 10 mètres avec une action mineure. Le profil d’une créature ou une règle particulière peut indiquer un déplacement différent.',action='1 action mineure · à son tour',effect='10 m pour un métahumain ordinaire.',limits='Une action Se déplacer par tour.',original='Se déplacer (I)',tags=('marcher','mouvement','distance déplacement'))
    P(49,'Se relever','Quitter l’état À terre en utilisant une action mineure à son tour.',action='1 action mineure',effect='Retirer À terre.',original='Se relever (I)',tags=('debout','prone'))
    P(49,'Se mettre à couvert','Prendre un abri et recevoir l’état Couvert I à IV selon la protection disponible. Le décor détermine les contraintes de position et de visibilité.',action='1 action mineure',original='Se mettre à couvert (I)',tags=('se cacher derrière','protection couvert'))
    P(50,'Observer attentivement','Examiner une scène ou un protagoniste pendant le combat. La présence évidente d’un adversaire est connue sans ce geste ; les détails et les individus cachés peuvent nécessiter le test.',test='Perception + Intuition ; Astral + Intuition pour l’observation astrale',threshold='Fixé par la difficulté ; contre Furtivité + Agilité si une cible se dissimule.',action='1 action majeure',original='Observer attentivement (I)',tags=('regarder','repérer détail','observer combat'))
    P(50,'Préparer une arme','Sortir et préparer une arme à feu ou de mêlée, ou armer une grenade. Une seule action peut préparer Agilité petites armes de jet dans l’autre main.',action='1 action majeure',original='Préparer une arme (I)',tags=('sortir arme','dégainer sans holster','ready weapon'))
    P(50,'Assister un coéquipier','Réserver une action majeure pour contribuer à un test d’équipe. Les assistants lancent avant le leader ; leurs succès lui ajoutent des dés dans la limite autorisée.',test='Test de l’assistant adapté à la tâche',action='1 action majeure · à tout moment',original='Assister (L)',tags=('aider','travail équipe','assistance'))
    P(102,'Escalader un mur','Les succès nets donnent chacun un mètre de progression dans la direction choisie. Le matériel d’escalade donne 1 Atout au début de l’ascension, pas à chaque jet.',test='Athlétisme + Force',threshold='3 ; +1 glissant, +1 lisse, +1 graissé ; −1 prises évidentes.',action='Utiliser une compétence · majeure si en combat',kit=('matériel d’escalade','grappin'),original='Escalade',tags=('grimper','escalader','mur','climbing'))
    P(102,'Se libérer de liens','Le type de lien fixe le seuil du test d’évasion. Les matériaux renforcés et la surveillance rendent l’opération plus difficile.',test='Athlétisme + Agilité',threshold='Corde ou menottes plastiques 2 ; métal 3 ; camisole 4 ; contention 5 ; matériau renforcé +1.',action='Utiliser une compétence',original='Évasion',tags=('menottes','se détacher','échapper liens','évasion'))
    P(102,'Nager','Le déplacement de base est de 3 mètres par round avec une action mineure. Un test de natation peut accroître cette distance.',test='Athlétisme + Agilité',threshold='2 ; augmenter en eaux difficiles et de 1 toutes les 15 minutes de nage.',effect='Ajouter ⌈succès nets / 2⌉ mètres à la distance.',original='Natation',tags=('nager','eau'))
    P(102,'Sauter en longueur','Avec élan, la distance de base est Agilité mètres et chaque succès net ajoute 50 cm ; sans élan, il ajoute 25 cm.',test='Athlétisme + Agilité',threshold='1',effect='Distance maximale : 1,5 × Agilité mètres.',original='Saut',tags=('sauter','franchir fossé','saut longueur'))
    P(105,'Repérer une personne cachée','Opposer directement l’observateur au personnage qui se dissimule. Un détail non caché utilise plutôt un seuil.',test='Perception + Intuition',opposition='Furtivité + Agilité',action='1 majeure Observer attentivement si nécessaire en combat',kit=('jumelles','vision nocturne','capteur'),original='Perception',tags=('chercher quelqu’un','voir ennemi caché','repérer','détecter embuscade'))
    P(106,'Remarquer un détail','Pour un élément de l’environnement, utiliser un seuil selon sa discrétion. Comprendre un motif ou un lien entre faits peut remplacer Intuition par Logique.',test='Perception + Intuition',threshold='1 évident/bruyant ; 2 normal ; 3 discret/petit ; 4 dissimulé/minuscule.',kit=('capteur','jumelles'),tags=('fouiller pièce','trouver indice','chercher passage secret','perception seuil'))
    P(103,'Se déplacer sans être repéré','Le personnage lance Furtivité + Agilité ; un observateur lance Perception + Intuition. L’éclairage, les capteurs et la dissimulation influencent la situation et l’Atout.',test='Furtivité + Agilité',opposition='Perception + Intuition',action='Utiliser une compétence',kit=('camouflage','combinaison','silencieux'),original='Furtivité',tags=('se faufiler','passer discrètement','infiltrer','discrétion','sneak'))
    P(103,'Mentir ou se faire passer pour quelqu’un','Escroquerie sert à persuader en jouant un rôle ou en masquant la vérité. La cible résiste avec ses attributs ; les succès nets mesurent l’efficacité de la tromperie.',test='Escroquerie + Charisme',opposition='Intuition + Volonté',action='Utiliser une compétence',kit=('déguisement','faux SIN'),original='Escroquerie',topic='personnage',tags=('bluffer','mentir','baratiner','imposture','convaincre mensonge'))
    P(105,'Négocier, intimider ou convaincre','Influence couvre négociation, intimidation, étiquette et leadership. Un raisonnement explicite peut faire utiliser Logique plutôt que Charisme.',test='Influence + Charisme ; ou Influence + Logique pour un argument rationnel',opposition='Volonté + Intuition ; Volonté + Logique si l’orateur emploie Logique',action='Utiliser une compétence',original='Influence',topic='personnage',tags=('négocier prix','intimider garde','convaincre','persuader','parler Johnson','social'))
    P(108,'Jauger les intentions d’un interlocuteur','Après avoir eu le temps de cerner une personne, évaluer ce qu’elle laisse transparaître. Le MJ décide du temps nécessaire et des informations accessibles.',test='Volonté + Intuition',original='Jauger les intentions (Volonté + Intuition)',topic='personnage',tags=('savoir ment','suspect','cerner Johnson','intentions'))
    P(108,'Se rappeler une information','Un test de Mémoire permet de retrouver un détail ou un fait ; son ancienneté et sa complexité fixent la difficulté.',test='Logique + Intuition',threshold='Déterminé par le MJ.',original='Mémoire (Logique + Intuition)',topic='personnage',tags=('souvenir','mémoire','se souvenir'))
    P(108,'Garder son sang-froid','Sous une pression exceptionnelle, tester si le personnage reste concentré. L’habitude de la situation peut rendre le test inutile.',test='Volonté + Charisme',threshold='Déterminé par le MJ selon le stress.',original='Sang-froid (Volonté + Charisme)',topic='personnage',tags=('peur','panique','stress','sang froid'))
    P(108,'Soulever ou transporter une charge','Sans test, soulever Force ×20 kg, ou Force ×5 kg au-dessus de la tête. Le test permet d’aller au-delà de cette capacité.',test='Constitution + Volonté',effect='+20 kg par succès net ; +10 kg au-dessus de la tête. VD 1E résistée avec Constitution, puis +1 VD par round de maintien.',original='Soulever / Transporter (Constitution + Volonté)',topic='personnage',tags=('porter blessé','charge lourde','soulever voiture'))
    P(105,'Crocheter une serrure','Utiliser Agilité, et non l’attribut de construction Logique, pour les serrures et maglocks. La complexité du dispositif fixe le seuil.',test='Ingénierie + Agilité',threshold='Selon la serrure ou le maglock.',action='Utiliser une compétence',kit=('outils de crochetage','autopass','séquenceur'),tags=('ouvrir porte verrouillée','crocheter','maglock','serrure','lockpick'))
    P(105,'Construire ou réparer du matériel','Un test étendu permet de cumuler les succès ; chaque intervalle exige les pièces et les outils adaptés.',test='Ingénierie + Logique · étendu',threshold='Véhicule grand public 7, industriel 9, militaire 11 ; électronique grand public 3, sous licence 4, illégale 5 ; objet spécialisé +1.',effect='Intervalle de base 1 h, ×2 pour complexe, ×4 pour important, ×10 pour complet.',kit=('kit d’outils','atelier','pièces détachées'),original='Ingénierie',tags=('réparer arme','réparation','construire','bricoler'))
    P(105,'Faire une réparation de fortune','Remettre provisoirement en marche un appareil avec un test simple ; une nouvelle tentative après la panne doit avoir un seuil au moins supérieur de 1.',test='Ingénierie + Intuition',threshold='Guide des seuils, selon la difficulté.',effect='Fonctionnement pendant succès nets minutes.',kit=('kit d’outils',),tags=('bricolage','dépanner','réparation temporaire'))
    P(106,'Piloter dans une situation difficile','Les manœuvres délicates emploient Pilotage + Réaction. Une compétition entre véhicules devient un test opposé.',test='Pilotage + Réaction',threshold='Selon la manœuvre ; opposition Pilotage + Réaction contre un conducteur.',action='Selon la manœuvre et le mode de contrôle',kit=('véhicule','câblage de contrôle'),original='Pilotage',topic='rigging',tags=('conduire','manœuvrer','poursuivre voiture','pilotage'))
    P(106,'Pister, survivre ou s’orienter','Plein air sert à suivre une piste, dénicher de quoi vivre et trouver son chemin. Les traces volontairement cachées peuvent déterminer le seuil de pistage.',test='Plein air + Intuition',threshold='Guide des seuils et circonstances de la piste.',action='Utiliser une compétence',kit=('survie','boussole','traceur'),original='Plein air',tags=('pister','trouver nourriture','se repérer','orientation','survie'))
    P(102,'Installer un implant cyberware','L’installation demande du matériel biotech approprié et un test étendu. Cette utilisation ne couvre pas l’installation des autres types de ware.',test='Biotech + Logique · étendu, intervalle 1 heure',threshold='Indice de l’implant ×3 ; indice par défaut 2 si l’implant n’en a pas.',kit=('atelier biotech','cyberware'),topic='personnage',tags=('chirurgie','installer cyberware','implanter'))
    P(125,'Administrer les premiers soins','Intervenir dans la minute suivant le combat ayant causé les blessures. Soigner les cases de surplus avant les autres blessures.',test='Biotech + Logique',threshold='5 − Essence de la cible ; +1 succès automatique si la cible est entièrement naturelle.',action='Une intervention dans la minute suivant le combat',effect='1 case E par succès net ; 1 case P ou de surplus pour 2 succès nets.',limits='Une tentative pour cette série de blessures. Sans kit : −2 dés et aucun Atout. Ne soigne pas le Drain.',kit=('kit de premiers soins',),original='Premiers soins',tags=('soigner un blessé','secourir','panser','first aid','guérison'),topic='personnage',example='Biotech 5 + LOG 4 = 9D6. Essence 3 : seuil 2. Avec 4 succès, il reste 2 succès nets : soigner 2E ou 1P.')
    P(126,'Soigner avec un médikit','Brancher le patient dans l’heure suivant le combat. Installation et diagnostic : 1 minute ; soin : 1 minute par case, avec une charge consommée.',test='Biotech + Logique ; ou indice du médikit + Logique',threshold='5 − Essence ; +1 succès automatique si le patient est entièrement naturel.',effect='1 case E, P ou de surplus par succès net.',limits='Une tentative pour la même série de blessures ; pas de soin du Drain ; charge nécessaire.',kit=('médikit','recharges de médikit'),original='Médikit',tags=('soigner médikit','medkit','médecine','guérir'),topic='personnage')
    P(126,'Soigner par magie','Lancer un sort de soins et résister à son Drain. Les succès nets soignent directement des cases ; le surplus est traité en premier.',test='Sorcellerie + Magie',threshold='5 − Essence de la cible',action='1 action majeure de lancement de sort',effect='1 case E, P ou de surplus par succès net.',limits='Une fois pour la même série de blessures ; ne soigne pas les dommages de Drain.',kit=('sort de soins',),tags=('sort soin','guérison magique','healing'),topic='magie')
    P(127,'Récupérer naturellement de ses blessures','Se reposer sans activité éprouvante. Les dommages étourdissants et physiques récupèrent en parallèle ; ne pas appliquer les malus de blessures à ces jets.',test='Constitution + Volonté',effect='E : 1 test par heure ; P : 1 test par jour. Chaque succès efface 1 case. Assistance Biotech pendant la moitié du repos : +2 dés.',limits='Surplus à soigner avant le retour à la conscience.',original='Récupération naturelle /assistance médicale',tags=('repos','guérison naturelle','récupération','dormir'),topic='personnage')
    P(127,'Résister à une toxine','Attendre le moment indiqué par la Rapidité puis opposer la résistance à la Virulence. Une protection n’aide que contre son vecteur d’exposition.',test='Constitution + Volonté + indice des protections adaptées',threshold='Virulence de la substance',effect='Chaque succès réduit la Virulence. À 0 : ni dommages ni effets, sauf exception explicite.',kit=('masque à gaz','filtre','isolation chimique','antidote'),tags=('poison','résistance toxine','gaz lacrymogène','toxines'),original='Virulence')
    P(114,'Déterminer si une embuscade surprend','Les organisateurs actifs de l’embuscade ne testent pas la surprise. Les autres testent avant de jouer leur premier round.',test='Réaction + Intuition',threshold='3, ajusté selon la préparation et la perception de la situation.',effect='Échec : aucune action ni dépense d’Atout au premier round ; les jets de défense et d’encaissement restent permis.',original='Surprise',tags=('embuscade','surpris','surprise test'))
    P(115,'Choisir un mode de tir','Le mode modifie le SO, la VD et les munitions utilisées ; il ne remplace pas le jet d’attaque.',effect='CC : 1 balle, inchangé. SA à 2 balles : SO −2, VD +1. TR ciblé : 4 balles, SO −4, VD +2. TA : 10 balles, SO −6, un jet contre toutes les cibles valides dans un rayon de 1 m.',limits='TR large : partager la réserve entre 2 cibles proches, chacune traitée en SA, sans Attaques multiples. TA : +1 m de rayon contre −2 SO, tant que le SO reste positif.',kit=('arme automatique','munitions'),original='Mode de tir',tags=('rafale','automatique','semi automatique','mode tir','TR','TA'))
    P(116,'Amortir une chute','Une chute de plus de 3 mètres inflige des dommages physiques. Un test athlétique relève la hauteur à partir de laquelle ces dommages commencent.',test='Athlétisme + Agilité ; puis Constitution pour résister',effect='Chaque succès net relève le seuil de chute de 1 m. VD de chute : moitié de la distance en mètres ; ajustement possible par le MJ.',tags=('tomber','chute','hauteur'))
    P(114,'Lire les portées d’une arme','Le profil donne un SO pour chacune des cinq bandes. Un tiret interdit d’utiliser cette arme à cette portée.',effect='Proche 0–3 m ; Courte 4–50 m ; Moyenne 51–250 m ; Longue 251–500 m ; Extrême au-delà de 500 m.',kit=('arme',),tags=('portées','distance tir','lire SO'))
    P(101,'Utiliser une compétence sans entraînement','Seules les compétences autorisant l’utilisation inexpérimentée peuvent être tentées sans rang. Une compétence entraînée ajoute son rang à l’attribut adapté.',test='Attribut associé −1 dé si inexpérimenté',limits='Spécialisation +2 ou maîtrise +3 ; ne pas cumuler les deux pour le même test.',topic='personnage',tags=('inexpérimenté','compétence zéro','spécialisation','maîtrise'))
    P(47,'Ajuster son tir','Se concentrer sur sa cible donne +1 dé à l’attaque suivante. Les actions successives peuvent cumuler ce bonus jusqu’à Volonté ; un tour sans Ajuster ni Attaquer fait perdre le bonus conservé.',action='1 action mineure',effect='+1 dé à la prochaine attaque ; maximum Volonté.',limits='Avec une lunette ou un grossissement d’image, la première action prépare le dispositif sans donner le dé supplémentaire.',kit=('lunette de visée',),original='Ajuster (I)',tags=('viser','prendre visée','aim'))
    P(49,'Recharger un smartgun','Éjecter le chargeur et engager un chargeur disponible grâce au smartlink connecté.',action='1 action mineure',kit=('smartgun','smartlink','chargeur'),original='Recharger un smartgun (I)',tags=('recharger','changer chargeur','reload'))
    P(50,'Recharger une arme sans smartlink','Recharger à pleine capacité avec les munitions disponibles. Utiliser cette procédure si le smartlink manque ou est désactivé.',action='1 action majeure',kit=('munitions','chargeur'),original='Recharger une arme (I)',tags=('recharger','reload'))
    P(49,'Se jeter à terre pour se défendre','Se jeter au sol donne +2 dés contre une attaque, puis impose À terre et une gêne temporaire.',action='1 action mineure · à tout moment',effect='+2 dés au test de défense ; ensuite −2 dés aux tests de compétences actives jusqu’à la fin du prochain tour ou jusqu’à Se relever.',original='Se jeter par terre (L)',tags=('plonger','se jeter par terre'))
    P(49,'Lâcher un objet','Abandonner ce que l’on tient en main. L’objet tombe et le MJ peut appliquer des dommages de chute à un objet fragile.',action='1 action mineure · à tout moment',original='Lâcher un objet (L)',tags=('lâcher','drop'))
    P(49,'Se coucher volontairement','S’allonger au sol impose l’état À terre jusqu’à l’action Se relever.',action='1 action mineure · à son tour',original='Se coucher (I)',tags=('s’allonger','à terre'))
    P(50,'Ramasser ou poser un objet','Prendre un objet à portée ou le déposer avec précaution. Une arme ramassée de cette manière est prête à l’emploi.',action='1 action majeure',original='Ramasser/Poser un objet (I)',tags=('ramasser','poser arme','objet au sol'))
    P(50,'Sprinter pendant un combat','Le sprint fournit un déplacement de base de 15 mètres, augmenté par les succès du test.',test='Athlétisme + Agilité',action='1 action majeure',effect='15 m +1 m par succès.',limits='Une fois par tour ; incompatible avec Se déplacer ou Éviter pendant ce round.',original='Sprinter (I)',tags=('courir','course','sprint','fuir à pied'))
    P(50,'Utiliser un appareil simple','Appuyer sur un bouton, une touche ou une icône pour déclencher une fonction simple. Un appareil complexe demande le temps de sa description.',action='1 action majeure ; 1 mineure si l’appareil est connecté à une IND active',original='Utiliser un appareil simple (I)',tags=('action bouton','interrupteur'))
    P(50,'Contrôler un drone à distance','Piloter à distance par une console de commande pour rigger demande une action majeure. Sans CCR, appliquer Contrôler un appareil.',action='1 action majeure',kit=('console de commande pour rigger','drone'),original='Contrôler un drone à distance (I)',topic='rigging',tags=('contrôler drone','piloter drone'))
    P(50,'Plonger dans un véhicule ou un drone','Prendre le contrôle immersif avec un câblage de contrôle et un véhicule ou drone adapté au rigging.',action='1 action majeure',kit=('câblage de contrôle','adaptation rigger'),original='Plonger (rigger) (I)',topic='rigging',tags=('immersion','plonger rigger','jump in'))
    P(152,'Invoquer un esprit','Choisir le type et la Puissance avant le jet. Un succès net au moins fait venir l’esprit ; chaque succès net fournit un service.',test='Conjuration + Magie',opposition='Puissance de l’esprit ×2 dés',action='1 action majeure',effect='Drain = tous les succès de l’esprit, résisté avec Volonté + attribut de tradition.',limits='Puissance cumulée des esprits actifs ≤ Magie ×3. Après résistance, Drain physique si supérieur à Magie ; sinon E.',kit=('réactifs',),original='Invocation',topic='magie',tags=('conjurer','summon','invoquer esprit'))
    P(153,'Bannir un esprit','Chaque succès net supprime un service. Quand le dernier service disparaît, l’esprit retourne à son métaplan.',test='Conjuration + Magie',opposition='Puissance de l’esprit ×2 dés',action='1 action majeure',effect='Drain = 2 × tous les succès de l’esprit ; résistance Volonté + attribut de tradition.',kit=('réactifs',),original='Bannissement',topic='magie',tags=('bannir','renvoyer esprit','banish'))
    P(148,'Protéger un groupe par contresort','Le contresort préventif renforce la défense contre les sorts dans une sphère de 2 mètres de rayon visible du mage.',test='Sorcellerie + Magie',action='1 action majeure Contrer un sort',effect='Ajouter les succès nets aux réserves de défense contre les sorts ; durée Magie rounds.',kit=('réactifs',),limits='Chaque drachme utilisée augmente le rayon de 1 m.',original='Défense augmentée',topic='magie',tags=('contresort','counterspell','défendre sort'))
    P(149,'Dissiper un sort','Contrer un sort maintenu ou à effet prolongé en réduisant ses succès nets.',test='Sorcellerie + Magie',opposition='Valeur de Drain du sort ×2 dés, ajustements inclus',action='1 action majeure Contrer un sort',effect='Chaque succès net annule un succès net du sort. À zéro, le sort est dissipé.',original='Dissipation',topic='magie',tags=('dissiper','contresort','annuler sort'))
    P(164,'Observer une aura astrale','Le nombre de succès détermine la précision des informations obtenues. La capacité à percevoir l’astral est nécessaire.',test='Astral + Intuition',action='Observation ; 1 majeure si en combat',effect='1 : santé, émotion, Éveil ; 2 : cyberware standard et type général de magie ; 3 : alphaware et comparaisons de Magie/Essence ; 4 : valeurs exactes et bioware/betaware ; 5+ : deltaware, nanotech et nature technomancienne.',original='Observation astrale',topic='magie',tags=('aura','assensing','observer astral'))
    P(165,'Combattre dans l’astral','Les attributs physiques sont remplacés par ceux de la forme astrale. Seuls les sorts mana peuvent y être utilisés.',test='Mains nues : Astral + Volonté ; focus d’arme : Combat rapproché + Volonté',opposition='Intuition + Logique',action='1 action majeure',effect='Mains nues : VD 2E + succès nets ; bonus de VD +1 si attribut de tradition ≥7, +2 si ≥10. Focus : VD de l’arme + succès nets, P ou E au choix.',kit=('focus d’arme',),original='Combat astral',topic='magie',tags=('attaque astrale','combat astral'))
    P(164,'Effacer sa signature astrale','Une signature persiste normalement Magie heures. Purifier retire l’équivalent d’une heure de persistance à un seul effet magique.',action='1 action majeure Purifier, sans test',effect='Répéter jusqu’à disparition de la signature.',original='Signatures astrales',topic='magie',tags=('purifier','traces astrales','signature'))
    P(195,'Compiler un sprite','Choisir un type et un niveau. Chaque succès net fournit une tâche ; le sprite non inscrit dure niveau ×2 heures.',test='Technomancie + Résonance',opposition='Niveau du sprite ×2 dés',effect='Technodrain = tous les succès du sprite ; résister avec Logique + Volonté.',limits='Un seul sprite non inscrit actif. Technodrain physique si, après résistance, il dépasse Résonance ; sinon E.',original='Compiler un sprite',topic='matrice',tags=('compiler','sprite','technomancien'))
    P(195,'Inscrire un sprite','Consacrer niveau heures au processus sans autre action pour le sprite ni son technomancien. Une réussite donne une durée indéfinie et ajoute les succès nets aux tâches dues.',test='Technomancie + Résonance',opposition='Niveau du sprite ×2 dés',effect='Technodrain = 2 × succès du sprite, minimum 2 ; résister avec Volonté + Logique.',limits='Au plus Résonance sprites inscrits ; pas d’augmentation du SS pendant le processus.',original='Inscrire un sprite',topic='matrice',tags=('enregistrer sprite','inscription'))
    P(196,'Décompiler un sprite','Chaque succès net retire une tâche au sprite ; lorsqu’il ne doit plus de tâche, il disparaît dans la Résonance.',test='Technomancie + Résonance',opposition='Niveau du sprite ; ajouter la Résonance de son créateur si inscrit.',original='Décompilation des sprites',topic='matrice',tags=('décompiler','supprimer sprite'))

    def M(page,title,summary,test='Aucun',opposition=None,access='Non nécessaire',action='Majeure',legal='Légale',effect=None,limits=None,tags=()):
        P(page,title.removesuffix(' (I)').removesuffix(' (L)'),summary,test=test,opposition=opposition,action=f'{action} · {legal.lower()} · accès {access}',effect=effect,limits=limits,kit=('cyberdeck','cyberjack'),original=title,topic='matrice',tags=tags)
        rules[-1]['procedure']['access']=access
    M(183,'Brouiller des signaux (I)','Transformer son appareil en brouilleur local dans un rayon de 100 mètres.',test='Piratage (Guerre électronique) + Logique',legal='Illégale',effect='Les succès ajoutent autant de Bruit dans la zone.',limits='L’effet cesse quand l’appareil est employé à une autre action matricielle.',tags=('brouiller','brouillage','signaux'))
