    M(185,'Empêtrer (I)','Infliger des dommages et ralentir le Traitement de données de la cible.',test='Piratage (Cybercombat) + Logique',opposition='Traitement de données + Firewall',access='Invité',legal='Illégale',effect='Dommages et réduction de Traitement de données : 1 + succès nets. Récupération de TD : 1 par round à partir du suivant.')
