    M(187,'Rechercher une empreinte numérique (I)','Réduire la liste des fichiers possibles grâce à une empreinte connue ou déduite.',test='Piratage (Hacking) + Logique',access='Utilisateur',legal='Illégale',effect='Seuil 1 avec empreinte fournie, 4 sans. Réussite : 32 fichiers possibles ; chaque succès net divise ce nombre par 2.',limits='Nouvelle tentative : −2 dés.',tags=('hash','fichier secret'))
