    M(188,'Traquer une icône (I)','Localiser physiquement un appareil ou un persona et conserver sa position tant qu’il reste détecté.',test='Électronique + Intuition',opposition='(Volonté ou Firewall) + Corruption',access='Administrateur',legal='Illégale',limits='Pas de localisation physique pour une CI ou un serveur purement virtuel.',tags=('localiser téléphone','trace icon'))
    M(188,'Vérifier son SS (I)','Connaître son Score de Surveillance actuel.',test='Piratage (Hacking) + Logique',legal='Illégale',effect='Seuil 4.',tags=('surveillance','overwatch','OS','SS'))
    P(183,'Réparer un appareil brické','Un appareil endommagé par la Matrice ne peut pas servir pendant la réparation. Une trousse à outils est nécessaire.',test='Ingénierie + Logique · étendu, 1 heure',threshold='Nombre de cases matricielles endommagées',limits='Un échec critique détruit définitivement l’appareil.',kit=('trousse à outils','cyberdeck'),original='Réparer des dommages matriciels',topic='matrice',tags=('réparer deck','brické','réparation matricielle'))

    enhancements={
        'Initiative':dict(test='Réaction + Intuition + somme des dés d’initiative',effect='Agir du score le plus élevé au plus faible ; ordre conservé sauf effet qui le modifie.'),
        'Résoudre une attaque':dict(test='Compétence d’attaque + Agilité ; Ingénierie + Logique pour une arme montée',opposition='Réaction + Intuition',effect='Succès nets ajoutés à la VD, puis résistance Constitution. Comparer SO/SD pour l’Atout.'),
        'Lancer un sort':dict(test='Sorcellerie + Magie',opposition='Selon le sort',action='1 action majeure',effect='Appliquer le sort puis résister au Drain avec Volonté + attribut de tradition.'),
        'Résister au Drain':dict(test='Volonté + attribut de tradition',effect='Chaque succès réduit le Drain de 1. Après résistance : P si supérieur à Magie, sinon E.'),
        'Intimider une créature':dict(test='Influence (Intimidation ou Créatures) + Charisme',opposition='Volonté + Intuition de la créature',action='1 action majeure',effect='Un round de recul par succès net ; indéfini si succès nets ≥ Volonté. Hostilité : effet terminé.'),
        'Apaiser une créature':dict(test='Influence (Créatures) + Charisme',opposition='Volonté + Intuition',action='1 action majeure, avec une offre adaptée',effect='Un round de tolérance par succès net ; indéfini si succès nets ≥ Volonté.'),
        'Localiser une créature sauvage':dict(test='Plein air (Pistage) + Intuition · étendu, intervalle 4 heures',threshold='Base +1D6 ; ordinaire 6, Éveillée 8 + MAG, Émergée 10 + RÉS. Voir la fiche pour rareté et Dissimulation.'),
    }
    for card in rules:
        if card['title'] in enhancements:card['procedure']=enhancements[card['title']];card['practical']=True
